def now() -> datetime:
    """Return the current time as naive UTC, the form stored in the table."""
    return datetime.now(UTC).replace(tzinfo=None)

@event.listens_for(Article, "before_insert")
def _stamp_created(
    _mapper: Mapper[Article], _connection: Connection, target: Article
) -> None:
    stamp = now()
    target.created_at = stamp
    target.updated_at = stamp

@event.listens_for(Article, "before_update")
def _stamp_updated(
    _mapper: Mapper[Article], _connection: Connection, target: Article
) -> None:
    session = object_session(target)
    if session is None or not session.is_modified(target):
        return
    target.updated_at = now()
    target.revision += 1

def edit(
    session: Session,
    article: Article,
    *,
    title: str | None = None,
    body: str | None = None,
) -> None:
    """Apply the given changes to an article and commit them."""
    if title is not None:
        if not title.strip():
            raise ValueError("title must not be blank")
        article.title = title
    if body is not None:
        article.body = body
    session.commit()
